import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";

import { validateCapabilityMatrix } from "../src/capability.ts";

const here = dirname(fileURLToPath(import.meta.url));
const matrixPath = resolve(here, "../../../specs/adapter-capabilities.v0.json");
const frozen = () => JSON.parse(readFileSync(matrixPath, "utf8"));

const derivedEventGroups = ["workspace_diff", "plan_state"];
const runtimeIds = ["codex", "claude-code"];
const invalidProofs: [string, unknown][] = [
  ["number", 123],
  ["object", { source: "runner filesystem" }],
  ["array", ["runner filesystem"]]
];

test("rejects non-string derivation proofs on otherwise honest unavailable derived cells", () => {
  const accepted: string[] = [];

  for (const eventGroup of derivedEventGroups) {
    for (const runtimeId of runtimeIds) {
      for (const [kind, proof] of invalidProofs) {
        const matrix = frozen();
        const cell = matrix.rows.find((row: any) => row.event_group === eventGroup).runtimes[runtimeId];
        const runtime = matrix.runtimes.find((entry: any) => entry.runtime_id === runtimeId);

        // Make the cell otherwise internally consistent with an unavailable derived capability.
        cell.derivation_proof = proof;
        cell.status = "UNAVAILABLE";
        runtime.supported_event_groups = runtime.supported_event_groups.filter(
          (entry: string) => entry !== eventGroup
        );
        runtime.known_missing_events = [eventGroup];

        if (validateCapabilityMatrix(matrix).ok) {
          accepted.push(`${eventGroup}/${runtimeId} accepted ${kind} derivation_proof`);
        }
      }
    }
  }

  assert.deepEqual(accepted, []);
});
